import pandas as pd


def _sig(city, tier):
    """Compute the legacy row signature:
    RTRIM(COALESCE(city, '')) || '|' || RTRIM(COALESCE(tier, ''))
    """
    def clean(x):
        if x is None:
            return ''
        try:
            if pd.isna(x):
                return ''
        except (TypeError, ValueError):
            pass
        s = str(x)
        return s.rstrip(' ')

    return clean(city) + '|' + clean(tier)


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    """Case-insensitive / flexible lookup of an input DataFrame by name."""
    if name in inputs:
        return inputs[name]
    # Try case-insensitive match
    lower_map = {k.lower(): k for k in inputs.keys()}
    if name.lower() in lower_map:
        return inputs[lower_map[name.lower()]]
    raise KeyError(name)


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, 'DIM_MEMBER').copy()
    stg = _get_input(inputs, 'STG_MEMBER').copy()

    # Work with a list of dict records so we can mutate "in place"
    # the same way the legacy UPDATE statement would.
    dim_records = dim.to_dict('records')

    # Map member_id -> index of the current (is_current == 1) row, if any.
    current_idx = {}
    for i, r in enumerate(dim_records):
        is_cur = r.get('is_current')
        try:
            is_cur_flag = int(is_cur) == 1
        except (TypeError, ValueError):
            is_cur_flag = False
        if is_cur_flag:
            # legacy assumption: at most one current row per member_id;
            # if duplicates exist, keep the first one encountered.
            current_idx.setdefault(r.get('member_id'), i)

    new_records = []

    for _, s in stg.iterrows():
        mid = s['member_id']
        s_city = s['city']
        s_tier = s['tier']
        s_update_date = s['update_date']

        if mid in current_idx:
            idx = current_idx[mid]
            c = dim_records[idx]

            if _sig(s_city, s_tier) != _sig(c.get('city'), c.get('tier')):
                # Close out the current row.
                dim_records[idx]['eff_end_date'] = s_update_date
                dim_records[idx]['is_current'] = 0

                # Insert new current row with staged values exactly as given.
                new_records.append({
                    'member_id': mid,
                    'city': s_city,
                    'tier': s_tier,
                    'eff_start_date': s_update_date,
                    'eff_end_date': pd.NaT,
                    'is_current': 1,
                })
            # else: signatures match -> no-op, current row stays as-is.
        else:
            # No current row for this member_id -> plain insert.
            new_records.append({
                'member_id': mid,
                'city': s_city,
                'tier': s_tier,
                'eff_start_date': s_update_date,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })

    all_records = dim_records + new_records

    out_cols = ['member_id', 'city', 'tier', 'eff_start_date', 'eff_end_date', 'is_current']
    out = pd.DataFrame(all_records, columns=out_cols)

    return {'dim_member_out': out}
